mapper.select:
select count(1)
from alert_action
where name = #{name}
  and id != #{id}

select id, name, label, icon, is_active as isActive, script as script, description as description from alert_action
and is_active = #{isActive}
and ( name like concat('%', #{keyword}, '%') or label like concat('%',#{keyword}, '%') )
and name in #{item}

mapper.delete:
delete
from alert_action_rel
where alert_id = #{alertId}
  and action_name = #{actionName}
